const btn=(label,action,extra='')=>`<button type="button" data-action="${action}" ${extra}>${label}</button>`;
function field(label,key,val,type='text',attrs='',group='data'){return `<label class="field">${label}${type==='textarea'?`<textarea data-bind="${group}.${key}" rows="4" ${attrs}>${esc(val)}</textarea>`:`<input data-bind="${group}.${key}" type="${type}" value="${esc(type==='color'?paintFallbackColor(val,'#ffffff',surfaceBackground(p,surface)):val)}" ${attrs}>`}</label>`}
function check(label,key,val,group='settings'){return `<label class="inlinecheck"><input type="checkbox" data-bind="${group}.${key}" ${val?'checked':''}>${label}</label>`}
function select(label,key,val,options,group='settings'){return `<label class="field">${label}<select data-bind="${group}.${key}">${options.map(([v,t])=>`<option value="${v}" ${String(v)===String(val)?'selected':''}>${t}</option>`).join('')}</select></label>`}
function prop(label,key,type='number',attrs=''){const l=['x','y','w','h','rotation'].includes(key)?editFrame():current(),value=key==='fontWeight'?(l.fontWeight||(l.bold?700:400)):l[key],display=type==='number'&&Number.isFinite(Number(value))?Number(Number(value).toFixed(3)):value;return `<label class="field">${label}${type==='textarea'?`<textarea data-prop="${key}" rows="4">${esc(l[key])}</textarea>`:`<input data-prop="${key}" type="${type}" value="${esc(type==='color'?paintFallbackColor(display,'#000000',surfaceBackground(p,surface)):display)}" ${attrs}>`}</label>`}
function propCheck(label,key){return `<label class="inlinecheck"><input data-prop="${key}" type="checkbox" ${(key==='visible'||key==='locked'?editFrame():current())[key]?'checked':''}>${label}</label>`}
function propSelect(label,key,options){return `<label class="field">${label}<select data-prop="${key}">${options.map(([v,t])=>`<option value="${esc(v)}" ${current()[key]===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
