function layerList(){return [...layers()].reverse().map(l=>`<div class="layerrow ${l.id===selected?'selected':''}"><button class="layername" data-action="select-layer" data-id="${l.id}">${esc(l.name)}</button><button data-action="visibility" data-id="${l.id}" aria-label="${l.visible?'Скрыть':'Показать'} ${esc(l.name)}">${l.visible?'◉':'○'}</button><button data-action="lock-layer" data-id="${l.id}" aria-label="Закрепить ${esc(l.name)}">${l.locked?'▣':'□'}</button></div>`).join('')}
