if(tab==='tracks'){html=`<div class="row">${btn('A','track-side','data-side="A" class="'+(trackSide==='A'?'active':'')+'"')}${btn('B','track-side','data-side="B" class="'+(trackSide==='B'?'active':'')+'"')}${btn('Текстом','bulk-tracks')}${btn('M3U на '+trackSide,'m3u')}${btn('Импорт на '+trackSide,'side-import')}</div>`+select('Длительность кассеты','capacity',p.settings.capacity,[[15,'C30 · 15 мин/сторона'],[30,'C60 · 30 мин/сторона'],[45,'C90 · 45 мин/сторона'],[60,'C120 · 60 мин/сторона']])+`<div class="capacity ${total(p.data[trackSide])>p.settings.capacity*60?'over':''}"><b>Сторона ${trackSide}</b><span>${time(total(p.data[trackSide]))} / ${p.settings.capacity}:00</span></div>`+p.data[trackSide].map((t,i)=>`<div class="trackrow" draggable="true" data-track="${i}"><span class="tracknum">${i+1}</span><input data-track-field="title" data-i="${i}" value="${esc(t.title)}" aria-label="Трек ${i+1}"><input data-track-field="seconds" data-i="${i}" value="${time(t.seconds)}" aria-label="Длительность ${i+1}"><input data-track-field="artist" data-i="${i}" value="${esc(t.artist)}" placeholder="Исполнитель" aria-label="Исполнитель трека ${i+1}" style="grid-column:2/4"><div class="trackactions">${btn('↑','track-up',`data-i="${i}"`)}${btn('↓','track-down',`data-i="${i}"`)}${btn('На '+(trackSide==='A'?'B':'A'),'track-move',`data-i="${i}"`)}${btn('✕','track-delete',`data-i="${i}"`)}</div></div>`).join('')+btn('＋ Добавить трек','add-track','class="wide"')+btn('Распределить A / B','balance','class="wide"')+btn('Поменять стороны местами','swap','class="wide"')+`<div class="section row">`+check('Номера','numbers',p.settings.numbers)+check('Длительность','durations',p.settings.durations)+check('Исполнители','artists',p.settings.artists)+check('Разделители','bullets',p.settings.bullets)+`</div><div class="two">`+field('Сторона A','sideA',p.settings.sideA,'text','','settings')+field('Сторона B','sideB',p.settings.sideB,'text','','settings')+`</div>`+field('Префикс стороны','sideText',p.settings.sideText,'text','','settings')+select('Разделитель названия','referenceSeparator',p.settings.referenceSeparator??'-',[['-','–'],['|','|'],[' ','Пробел'],['•','•'],['·','·']])+(mode==='jcard'?`<h3>Треки на внутренней стороне</h3>${['A','B'].map(side=>btn((p.surfaces.inner.some(l=>l.category==='insideTracks'&&l.visible&&(l.source===side||l.source==='referenceContents'&&!l['hide'+side]))?'Скрыть':'Показать')+' '+side+' внутри','inside-tracks',`data-side="${side}"`)).join('')}`:'')+btn('Скачать M3U','export-m3u','class="wide"')}
