function pickGoogleFont(layer,album=false){
 const project=p,sf=surface,joined=joinColumns;
 fontPicker({modal,request,esc,apply:async font=>{
  if(p!==project||surface!==sf||!layers().includes(layer))throw Error('Макет изменился. Выберите шрифт заново.');
  if(!canEditLayer(selectionFrame(project,layer,sf,joined),'font'))throw Error('Слой закреплён. Сначала снимите закрепление.');
  const same=f=>f.name===font.name&&(f.weight||400)===font.weight&&(f.style||'normal')===font.style;
  if(project.fonts.length>=80&&!project.fonts.some(same))throw Error('В проекте уже 80 начертаний');
  checkpoint(true);project.fonts=project.fonts.filter(f=>!same(f));project.fonts.push(font);
  if(album){changeAlbumTextStyle(layer,'font',font.name);changeAlbumTextStyle(layer,'fontWeight',font.weight);changeAlbumTextStyle(layer,'italic',font.style==='italic')}
  else for(const [key,value] of Object.entries({font:font.name,fontWeight:font.weight,bold:font.weight>=700,italic:font.style==='italic'}))setSelectionProperty(project,layer,sf,key,value,joined);
  changed({inspector:true,mirrorLayers:true});toast('Шрифт сохранён в проекте');
 }});
}
